import{_ as t,c as o,o as a,a2 as g}from"./chunks/framework.B7el9cAC.js";const d=JSON.parse('{"title":"Mục 2.4 – Mô Hình OSI","description":"","frontmatter":{},"headers":[],"relativePath":"chuong-2/2.4-mo-hinh-osi.md","filePath":"chuong-2/2.4-mo-hinh-osi.md","lastUpdated":1775359730000}'),i={name:"chuong-2/2.4-mo-hinh-osi.md"};function h(r,n,e,s,c,l){return a(),o("div",null,[...n[0]||(n[0]=[g(`<h1 id="muc-2-4-–-mo-hinh-osi" tabindex="-1">Mục 2.4 – Mô Hình OSI <a class="header-anchor" href="#muc-2-4-–-mo-hinh-osi" aria-label="Permalink to &quot;Mục 2.4 – Mô Hình OSI&quot;">​</a></h1><blockquote><p><strong>Chương 2: Mạng máy tính và Internet</strong></p></blockquote><hr><h2 id="🔹-1-gioi-thieu-sieu-co-ban" tabindex="-1">🔹 1. GIỚI THIỆU SIÊU CƠ BẢN <a class="header-anchor" href="#🔹-1-gioi-thieu-sieu-co-ban" aria-label="Permalink to &quot;🔹 1. GIỚI THIỆU SIÊU CƠ BẢN&quot;">​</a></h2><h3 id="tai-sao-can-mo-hinh-osi" tabindex="-1">Tại sao cần mô hình OSI? <a class="header-anchor" href="#tai-sao-can-mo-hinh-osi" aria-label="Permalink to &quot;Tại sao cần mô hình OSI?&quot;">​</a></h3><p>Hãy tưởng tượng bạn gửi một bức thư quốc tế: Bạn viết thư → bỏ vào phong bì → ghi địa chỉ → đưa cho bưu điện → xe chở đến sân bay → máy bay chở sang nước khác → xe chở đến bưu cục → người đưa thư mang đến nhà → người nhận bóc thư ra đọc. Mỗi bước là một <strong>khâu riêng biệt</strong>, có vai trò riêng, không cần biết các khâu khác làm gì.</p><p><strong>Mô hình OSI</strong> cũng hoạt động tương tự: khi bạn gửi dữ liệu qua mạng, dữ liệu đó đi qua <strong>7 tầng (layer)</strong> khác nhau, mỗi tầng xử lý một phần việc cụ thể.</p><p><strong>Tại sao quan trọng?</strong></p><ul><li>Trước OSI, mỗi hãng máy tính (IBM, DEC, HP...) tạo ra giao thức mạng riêng, các hãng khác không thể kết nối được.</li><li>OSI ra đời năm 1984 (do ISO ban hành) để <strong>chuẩn hóa</strong> cách các hệ thống mạng khác nhau giao tiếp với nhau.</li><li>Dù TCP/IP được dùng thực tế nhiều hơn, OSI vẫn là <strong>nền tảng lý thuyết</strong> để hiểu mạng máy tính.</li></ul><hr><h2 id="🔹-2-ly-thuyet-chi-tiet" tabindex="-1">🔹 2. LÝ THUYẾT CHI TIẾT <a class="header-anchor" href="#🔹-2-ly-thuyet-chi-tiet" aria-label="Permalink to &quot;🔹 2. LÝ THUYẾT CHI TIẾT&quot;">​</a></h2><h3 id="_2-1-mo-hinh-osi-la-gi" tabindex="-1">2.1 Mô hình OSI là gì? <a class="header-anchor" href="#_2-1-mo-hinh-osi-la-gi" aria-label="Permalink to &quot;2.1 Mô hình OSI là gì?&quot;">​</a></h3><p><strong>OSI (Open Systems Interconnection)</strong> là mô hình tham chiếu 7 tầng, mô tả cách dữ liệu được truyền từ ứng dụng của máy tính này sang ứng dụng của máy tính khác qua mạng.</p><blockquote><p>&quot;Open Systems&quot; = Hệ thống mở – nghĩa là bất kỳ thiết bị nào cũng có thể giao tiếp với nhau nếu tuân theo chuẩn.</p></blockquote><h3 id="_2-2-bay-tang-cua-mo-hinh-osi" tabindex="-1">2.2 Bảy tầng của mô hình OSI <a class="header-anchor" href="#_2-2-bay-tang-cua-mo-hinh-osi" aria-label="Permalink to &quot;2.2 Bảy tầng của mô hình OSI&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Số tầng</th><th>Tên tầng</th><th>Tên tiếng Việt</th><th>Chức năng chính</th></tr></thead><tbody><tr><td><strong>7</strong></td><td>Application</td><td>Tầng Ứng dụng</td><td>Giao tiếp với phần mềm người dùng</td></tr><tr><td><strong>6</strong></td><td>Presentation</td><td>Tầng Trình bày</td><td>Mã hóa, nén, chuyển đổi định dạng</td></tr><tr><td><strong>5</strong></td><td>Session</td><td>Tầng Phiên</td><td>Thiết lập, quản lý, kết thúc phiên làm việc</td></tr><tr><td><strong>4</strong></td><td>Transport</td><td>Tầng Vận chuyển</td><td>Phân mảnh, TCP/UDP, kiểm soát lỗi</td></tr><tr><td><strong>3</strong></td><td>Network</td><td>Tầng Mạng</td><td>Địa chỉ IP, định tuyến</td></tr><tr><td><strong>2</strong></td><td>Data Link</td><td>Tầng Liên kết dữ liệu</td><td>Địa chỉ MAC, phát hiện lỗi vật lý</td></tr><tr><td><strong>1</strong></td><td>Physical</td><td>Tầng Vật lý</td><td>Truyền bit qua cáp, sóng vô tuyến</td></tr></tbody></table><blockquote><p><strong>Mẹo nhớ (từ trên xuống):</strong> &quot;<strong>A</strong>ll <strong>P</strong>eople <strong>S</strong>eem <strong>T</strong>o <strong>N</strong>eed <strong>D</strong>ata <strong>P</strong>rocessing&quot; → Application, Presentation, Session, Transport, Network, Data Link, Physical</p></blockquote><h3 id="_2-3-chi-tiet-tung-tang" tabindex="-1">2.3 Chi tiết từng tầng <a class="header-anchor" href="#_2-3-chi-tiet-tung-tang" aria-label="Permalink to &quot;2.3 Chi tiết từng tầng&quot;">​</a></h3><h4 id="🔵-tang-7-–-application-ung-dung" tabindex="-1">🔵 Tầng 7 – Application (Ứng dụng) <a class="header-anchor" href="#🔵-tang-7-–-application-ung-dung" aria-label="Permalink to &quot;🔵 Tầng 7 – Application (Ứng dụng)&quot;">​</a></h4><ul><li><strong>Chức năng:</strong> Cung cấp giao diện giữa ứng dụng và mạng.</li><li><strong>Đây là tầng duy nhất người dùng tương tác trực tiếp</strong>.</li><li>Không phải là phần mềm ứng dụng (như Chrome hay Word), mà là giao thức ứng dụng.</li><li><strong>Giao thức:</strong> HTTP/HTTPS (web), SMTP/POP3/IMAP (email), FTP (truyền file), DNS (phân giải tên miền).</li><li><strong>Đơn vị dữ liệu:</strong> Data (dữ liệu).</li></ul><h4 id="🟢-tang-6-–-presentation-trinh-bay" tabindex="-1">🟢 Tầng 6 – Presentation (Trình bày) <a class="header-anchor" href="#🟢-tang-6-–-presentation-trinh-bay" aria-label="Permalink to &quot;🟢 Tầng 6 – Presentation (Trình bày)&quot;">​</a></h4><ul><li><strong>Chức năng:</strong> Chuyển đổi, mã hóa, nén dữ liệu để tầng Application có thể đọc được.</li><li><strong>Ví dụ:</strong><ul><li>Mã hóa SSL/TLS (khi bạn truy cập website HTTPS).</li><li>Nén dữ liệu (ZIP, JPEG, MP3).</li><li>Chuyển đổi định dạng ký tự (ASCII sang Unicode).</li></ul></li><li><strong>Đơn vị dữ liệu:</strong> Data.</li></ul><h4 id="🟡-tang-5-–-session-phien" tabindex="-1">🟡 Tầng 5 – Session (Phiên) <a class="header-anchor" href="#🟡-tang-5-–-session-phien" aria-label="Permalink to &quot;🟡 Tầng 5 – Session (Phiên)&quot;">​</a></h4><ul><li><strong>Chức năng:</strong> Thiết lập, duy trì, và kết thúc &quot;phiên&quot; (session) giao tiếp giữa hai máy.</li><li><strong>Ví dụ:</strong><ul><li>Khi bạn đăng nhập vào Facebook, tầng Session duy trì phiên đăng nhập đó cho đến khi bạn đăng xuất.</li><li>Khi mạng bị ngắt giữa chừng trong khi tải file, tầng Session cho phép <strong>tiếp tục</strong> từ điểm bị ngắt (resume).</li></ul></li><li><strong>Đơn vị dữ liệu:</strong> Data.</li></ul><h4 id="🔴-tang-4-–-transport-van-chuyen" tabindex="-1">🔴 Tầng 4 – Transport (Vận chuyển) <a class="header-anchor" href="#🔴-tang-4-–-transport-van-chuyen" aria-label="Permalink to &quot;🔴 Tầng 4 – Transport (Vận chuyển)&quot;">​</a></h4><ul><li><strong>Chức năng:</strong> Truyền dữ liệu đáng tin cậy từ đầu cuối đến đầu cuối (end-to-end).</li><li>Chia dữ liệu thành các <strong>segment</strong> (TCP) hoặc <strong>datagram</strong> (UDP).</li><li>Đánh số thứ tự, xác nhận (ACK), gửi lại nếu mất (TCP).</li><li><strong>Giao thức:</strong> TCP (tin cậy, chậm hơn), UDP (nhanh, không tin cậy).</li><li>Dùng <strong>số cổng (port)</strong> để phân biệt ứng dụng: HTTP=80, HTTPS=443, SMTP=25, FTP=21.</li><li><strong>Đơn vị dữ liệu:</strong> Segment (TCP) / Datagram (UDP).</li></ul><h4 id="🟠-tang-3-–-network-mang" tabindex="-1">🟠 Tầng 3 – Network (Mạng) <a class="header-anchor" href="#🟠-tang-3-–-network-mang" aria-label="Permalink to &quot;🟠 Tầng 3 – Network (Mạng)&quot;">​</a></h4><ul><li><strong>Chức năng:</strong> Định tuyến gói tin từ nguồn đến đích qua nhiều mạng trung gian.</li><li>Dùng <strong>địa chỉ IP</strong> (logic) để nhận diện thiết bị.</li><li>Thiết bị hoạt động ở tầng này: <strong>Router</strong>.</li><li><strong>Giao thức:</strong> IP, ICMP (ping), ARP.</li><li><strong>Đơn vị dữ liệu:</strong> Packet (gói tin).</li></ul><h4 id="🟤-tang-2-–-data-link-lien-ket-du-lieu" tabindex="-1">🟤 Tầng 2 – Data Link (Liên kết dữ liệu) <a class="header-anchor" href="#🟤-tang-2-–-data-link-lien-ket-du-lieu" aria-label="Permalink to &quot;🟤 Tầng 2 – Data Link (Liên kết dữ liệu)&quot;">​</a></h4><ul><li><strong>Chức năng:</strong> Truyền dữ liệu tin cậy giữa hai node kết nối trực tiếp, phát hiện lỗi vật lý.</li><li>Dùng <strong>địa chỉ MAC</strong> để nhận diện thiết bị trong cùng mạng.</li><li>Thiết bị hoạt động ở tầng này: <strong>Switch</strong>, Bridge.</li><li>Chia thành 2 lớp con: <ul><li><strong>LLC (Logical Link Control):</strong> Kiểm soát luồng.</li><li><strong>MAC (Media Access Control):</strong> Địa chỉ vật lý, điều khiển truy cập.</li></ul></li><li><strong>Đơn vị dữ liệu:</strong> Frame (khung).</li></ul><h4 id="⚫-tang-1-–-physical-vat-ly" tabindex="-1">⚫ Tầng 1 – Physical (Vật lý) <a class="header-anchor" href="#⚫-tang-1-–-physical-vat-ly" aria-label="Permalink to &quot;⚫ Tầng 1 – Physical (Vật lý)&quot;">​</a></h4><ul><li><strong>Chức năng:</strong> Truyền các bit (0 và 1) dưới dạng tín hiệu điện, tín hiệu quang, hoặc sóng vô tuyến qua môi trường truyền dẫn.</li><li>Quy định: điện áp, tần số sóng, loại đầu cắm, loại cáp.</li><li>Thiết bị: Hub, Repeater, cáp Ethernet, cáp quang, anten Wi-Fi.</li><li><strong>Đơn vị dữ liệu:</strong> Bit.</li></ul><hr><h2 id="🔹-3-giai-thich-ban-chat" tabindex="-1">🔹 3. GIẢI THÍCH BẢN CHẤT <a class="header-anchor" href="#🔹-3-giai-thich-ban-chat" aria-label="Permalink to &quot;🔹 3. GIẢI THÍCH BẢN CHẤT&quot;">​</a></h2><h3 id="qua-trinh-đong-goi-du-lieu-encapsulation" tabindex="-1">Quá trình đóng gói dữ liệu (Encapsulation) <a class="header-anchor" href="#qua-trinh-đong-goi-du-lieu-encapsulation" aria-label="Permalink to &quot;Quá trình đóng gói dữ liệu (Encapsulation)&quot;">​</a></h3><p>Khi gửi dữ liệu, dữ liệu đi <strong>từ tầng 7 xuống tầng 1</strong>, mỗi tầng <strong>thêm vào một &quot;tiêu đề&quot; (header)</strong> của tầng đó:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Tầng 7] Data</span></span>
<span class="line"><span>[Tầng 6] Data</span></span>
<span class="line"><span>[Tầng 5] Data</span></span>
<span class="line"><span>[Tầng 4] TCP Header | Data                        ← Segment</span></span>
<span class="line"><span>[Tầng 3] IP Header | TCP Header | Data            ← Packet</span></span>
<span class="line"><span>[Tầng 2] MAC Header | IP Header | TCP Header | Data | MAC Trailer  ← Frame</span></span>
<span class="line"><span>[Tầng 1] 01001011010010110...                     ← Bits</span></span></code></pre></div><p>Khi nhận dữ liệu, dữ liệu đi <strong>từ tầng 1 lên tầng 7</strong>, mỗi tầng <strong>bóc ra một tiêu đề</strong> của tầng đó (De-encapsulation).</p><blockquote><p><strong>Hình dung:</strong> Giống như bọc quà nhiều lớp – người nhận phải bóc từng lớp từ ngoài vào trong để lấy món quà thực sự.</p></blockquote><h3 id="điem-quan-trong-can-nho" tabindex="-1">Điểm quan trọng cần nhớ <a class="header-anchor" href="#điem-quan-trong-can-nho" aria-label="Permalink to &quot;Điểm quan trọng cần nhớ&quot;">​</a></h3><ul><li>Tầng <strong>7,6,5</strong> → xử lý bởi phần mềm ứng dụng.</li><li>Tầng <strong>4</strong> → TCP/UDP – kiểm soát truyền tải.</li><li>Tầng <strong>3</strong> → IP – định tuyến, Router hoạt động ở đây.</li><li>Tầng <strong>2</strong> → MAC – trong LAN, Switch hoạt động ở đây.</li><li>Tầng <strong>1</strong> → Tín hiệu vật lý – cáp, sóng Wi-Fi.</li></ul><hr><h2 id="🔹-4-luong-hoat-đong-step-by-step" tabindex="-1">🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP <a class="header-anchor" href="#🔹-4-luong-hoat-đong-step-by-step" aria-label="Permalink to &quot;🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP&quot;">​</a></h2><h3 id="gui-email-luong-du-lieu-qua-7-tang-osi" tabindex="-1">Gửi email: luồng dữ liệu qua 7 tầng OSI <a class="header-anchor" href="#gui-email-luong-du-lieu-qua-7-tang-osi" aria-label="Permalink to &quot;Gửi email: luồng dữ liệu qua 7 tầng OSI&quot;">​</a></h3><p><strong>Tình huống:</strong> Bạn gửi email từ máy tính của mình đến bạn bè ở thành phố khác.</p><p><strong>Phía người gửi (xuống từ tầng 7 → 1):</strong></p><table tabindex="0"><thead><tr><th>Tầng</th><th>Hành động</th></tr></thead><tbody><tr><td><strong>7 – Application</strong></td><td>Gmail tạo email (văn bản + file). Dùng giao thức SMTP.</td></tr><tr><td><strong>6 – Presentation</strong></td><td>Mã hóa nội dung email (TLS), chuyển sang định dạng MIME.</td></tr><tr><td><strong>5 – Session</strong></td><td>Mở phiên kết nối với máy chủ Gmail.</td></tr><tr><td><strong>4 – Transport</strong></td><td>TCP chia email thành các segment, gắn port nguồn (ngẫu nhiên) và port đích (SMTP=25).</td></tr><tr><td><strong>3 – Network</strong></td><td>IP đóng gói segment thành packet, gắn IP nguồn và IP đích (máy chủ Gmail).</td></tr><tr><td><strong>2 – Data Link</strong></td><td>Gắn địa chỉ MAC nguồn và MAC đích (router/gateway). Tạo Frame.</td></tr><tr><td><strong>1 – Physical</strong></td><td>Chuyển frame thành tín hiệu điện/quang và truyền qua cáp.</td></tr></tbody></table><p><strong>Phía người nhận (lên từ tầng 1 → 7) – ngược lại hoàn toàn.</strong></p><hr><h2 id="🔹-5-vi-du-minh-hoa" tabindex="-1">🔹 5. VÍ DỤ MINH HỌA <a class="header-anchor" href="#🔹-5-vi-du-minh-hoa" aria-label="Permalink to &quot;🔹 5. VÍ DỤ MINH HỌA&quot;">​</a></h2><h3 id="vi-du-1-–-co-ban-nhan-dien-tang-osi-tu-thiet-bi" tabindex="-1">Ví dụ 1 – Cơ bản: Nhận diện tầng OSI từ thiết bị <a class="header-anchor" href="#vi-du-1-–-co-ban-nhan-dien-tang-osi-tu-thiet-bi" aria-label="Permalink to &quot;Ví dụ 1 – Cơ bản: Nhận diện tầng OSI từ thiết bị&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Thiết bị</th><th>Tầng OSI</th><th>Giải thích</th></tr></thead><tbody><tr><td>Hub</td><td>Tầng 1 (Physical)</td><td>Chỉ khuếch đại tín hiệu, không đọc địa chỉ</td></tr><tr><td>Switch</td><td>Tầng 2 (Data Link)</td><td>Đọc địa chỉ MAC để chuyển frame</td></tr><tr><td>Router</td><td>Tầng 3 (Network)</td><td>Đọc địa chỉ IP để định tuyến packet</td></tr><tr><td>Firewall</td><td>Tầng 3-7</td><td>Lọc dựa trên IP, port, nội dung</td></tr><tr><td>Trình duyệt web</td><td>Tầng 7 (Application)</td><td>Dùng HTTP/HTTPS</td></tr></tbody></table><h3 id="vi-du-2-–-thuc-te-xac-đinh-tang-osi-tu-giao-thuc" tabindex="-1">Ví dụ 2 – Thực tế: Xác định tầng OSI từ giao thức <a class="header-anchor" href="#vi-du-2-–-thuc-te-xac-đinh-tang-osi-tu-giao-thuc" aria-label="Permalink to &quot;Ví dụ 2 – Thực tế: Xác định tầng OSI từ giao thức&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Giao thức</th><th>Tầng OSI</th><th>Ứng dụng</th></tr></thead><tbody><tr><td>HTTP/HTTPS</td><td>Tầng 7</td><td>Truy cập web</td></tr><tr><td>SMTP/POP3/IMAP</td><td>Tầng 7</td><td>Email</td></tr><tr><td>FTP</td><td>Tầng 7</td><td>Truyền file</td></tr><tr><td>DNS</td><td>Tầng 7</td><td>Phân giải tên miền</td></tr><tr><td>SSL/TLS</td><td>Tầng 6</td><td>Mã hóa dữ liệu</td></tr><tr><td>TCP</td><td>Tầng 4</td><td>Truyền tin cậy</td></tr><tr><td>UDP</td><td>Tầng 4</td><td>Truyền nhanh</td></tr><tr><td>IP</td><td>Tầng 3</td><td>Định tuyến</td></tr><tr><td>Ethernet</td><td>Tầng 2</td><td>Mạng LAN có dây</td></tr><tr><td>Wi-Fi (802.11)</td><td>Tầng 2</td><td>Mạng không dây</td></tr></tbody></table><h3 id="vi-du-3-–-nang-cao-so-sanh-osi-va-tcp-ip" tabindex="-1">Ví dụ 3 – Nâng cao: So sánh OSI và TCP/IP <a class="header-anchor" href="#vi-du-3-–-nang-cao-so-sanh-osi-va-tcp-ip" aria-label="Permalink to &quot;Ví dụ 3 – Nâng cao: So sánh OSI và TCP/IP&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Mô hình OSI              Mô hình TCP/IP</span></span>
<span class="line"><span>─────────────────        ─────────────────────</span></span>
<span class="line"><span>7. Application  ┐</span></span>
<span class="line"><span>6. Presentation ├──────► Application (HTTP, FTP, SMTP...)</span></span>
<span class="line"><span>5. Session      ┘</span></span>
<span class="line"><span>─────────────────        ─────────────────────</span></span>
<span class="line"><span>4. Transport    ───────► Transport (TCP, UDP)</span></span>
<span class="line"><span>─────────────────        ─────────────────────</span></span>
<span class="line"><span>3. Network      ───────► Internet (IP, ICMP, ARP)</span></span>
<span class="line"><span>─────────────────        ─────────────────────</span></span>
<span class="line"><span>2. Data Link    ┐</span></span>
<span class="line"><span>1. Physical     ├──────► Network Access (Ethernet, Wi-Fi)</span></span>
<span class="line"><span>                ┘</span></span></code></pre></div><blockquote><p>Mô hình TCP/IP gộp tầng 7+6+5 thành <strong>Application</strong>, và gộp tầng 2+1 thành <strong>Network Access</strong>.</p></blockquote><hr><h2 id="🔹-6-so-sanh-phan-biet" tabindex="-1">🔹 6. SO SÁNH &amp; PHÂN BIỆT <a class="header-anchor" href="#🔹-6-so-sanh-phan-biet" aria-label="Permalink to &quot;🔹 6. SO SÁNH &amp; PHÂN BIỆT&quot;">​</a></h2><h3 id="osi-vs-tcp-ip" tabindex="-1">OSI vs TCP/IP <a class="header-anchor" href="#osi-vs-tcp-ip" aria-label="Permalink to &quot;OSI vs TCP/IP&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>OSI</th><th>TCP/IP</th></tr></thead><tbody><tr><td><strong>Số tầng</strong></td><td>7</td><td>4</td></tr><tr><td><strong>Mục đích</strong></td><td>Lý thuyết, tham chiếu</td><td>Thực tế, được dùng trên Internet</td></tr><tr><td><strong>Phát triển</strong></td><td>ISO (1984)</td><td>DoD/ARPANET (1970s)</td></tr><tr><td><strong>Ứng dụng</strong></td><td>Học tập, chuẩn hóa</td><td>Hoạt động thực tế của Internet</td></tr><tr><td><strong>Độ linh hoạt</strong></td><td>Cứng nhắc hơn</td><td>Linh hoạt hơn</td></tr></tbody></table><h3 id="đon-vi-du-lieu-o-tung-tang" tabindex="-1">Đơn vị dữ liệu ở từng tầng <a class="header-anchor" href="#đon-vi-du-lieu-o-tung-tang" aria-label="Permalink to &quot;Đơn vị dữ liệu ở từng tầng&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tầng</th><th>Tên đơn vị dữ liệu</th></tr></thead><tbody><tr><td>Tầng 7, 6, 5</td><td>Data (dữ liệu)</td></tr><tr><td>Tầng 4</td><td>Segment (TCP) / Datagram (UDP)</td></tr><tr><td>Tầng 3</td><td>Packet (gói tin)</td></tr><tr><td>Tầng 2</td><td>Frame (khung)</td></tr><tr><td>Tầng 1</td><td>Bit</td></tr></tbody></table><hr><h2 id="🔹-7-ghi-nho-nhanh-đi-thi" tabindex="-1">🔹 7. GHI NHỚ NHANH (ĐI THI) <a class="header-anchor" href="#🔹-7-ghi-nho-nhanh-đi-thi" aria-label="Permalink to &quot;🔹 7. GHI NHỚ NHANH (ĐI THI)&quot;">​</a></h2><ul><li>🏗️ OSI có <strong>7 tầng</strong> – từ trên xuống: <strong>Application → Physical</strong></li><li>🔑 Mẹo nhớ: <strong>&quot;All People Seem To Need Data Processing&quot;</strong></li><li>📱 Tầng <strong>7 (Application):</strong> HTTP, HTTPS, FTP, SMTP, DNS</li><li>🔐 Tầng <strong>6 (Presentation):</strong> Mã hóa SSL/TLS, nén ZIP/JPEG</li><li>🔗 Tầng <strong>5 (Session):</strong> Quản lý phiên đăng nhập</li><li>📦 Tầng <strong>4 (Transport):</strong> TCP/UDP, port, phân mảnh → đơn vị: <strong>Segment</strong></li><li>🌐 Tầng <strong>3 (Network):</strong> IP, Router, định tuyến → đơn vị: <strong>Packet</strong></li><li>🖥️ Tầng <strong>2 (Data Link):</strong> MAC, Switch, Ethernet → đơn vị: <strong>Frame</strong></li><li>⚡ Tầng <strong>1 (Physical):</strong> Cáp, sóng, Hub → đơn vị: <strong>Bit</strong></li><li>🔄 Gửi dữ liệu: đóng gói từ <strong>tầng 7 → 1</strong> (thêm header mỗi tầng)</li><li>🔄 Nhận dữ liệu: bóc gói từ <strong>tầng 1 → 7</strong> (bỏ header mỗi tầng)</li><li>🔵 <strong>Router</strong> ↔ Tầng 3 | <strong>Switch</strong> ↔ Tầng 2 | <strong>Hub</strong> ↔ Tầng 1</li></ul><hr><h2 id="🔹-8-bai-tap-tu-luyen" tabindex="-1">🔹 8. BÀI TẬP TỰ LUYỆN <a class="header-anchor" href="#🔹-8-bai-tap-tu-luyen" aria-label="Permalink to &quot;🔹 8. BÀI TẬP TỰ LUYỆN&quot;">​</a></h2><h3 id="cau-1-de-đien-vao-bang" tabindex="-1">Câu 1 (Dễ): Điền vào bảng <a class="header-anchor" href="#cau-1-de-đien-vao-bang" aria-label="Permalink to &quot;Câu 1 (Dễ): Điền vào bảng&quot;">​</a></h3><blockquote><p>Điền tên tầng OSI và đơn vị dữ liệu tương ứng vào bảng sau:</p></blockquote><table tabindex="0"><thead><tr><th>Số tầng</th><th>Tên tầng</th><th>Đơn vị dữ liệu</th></tr></thead><tbody><tr><td>7</td><td>?</td><td>?</td></tr><tr><td>4</td><td>?</td><td>?</td></tr><tr><td>3</td><td>?</td><td>?</td></tr><tr><td>2</td><td>?</td><td>?</td></tr><tr><td>1</td><td>?</td><td>?</td></tr></tbody></table><p><strong>Đáp án:</strong></p><table tabindex="0"><thead><tr><th>Số tầng</th><th>Tên tầng</th><th>Đơn vị dữ liệu</th></tr></thead><tbody><tr><td>7</td><td>Application</td><td>Data</td></tr><tr><td>4</td><td>Transport</td><td>Segment</td></tr><tr><td>3</td><td>Network</td><td>Packet</td></tr><tr><td>2</td><td>Data Link</td><td>Frame</td></tr><tr><td>1</td><td>Physical</td><td>Bit</td></tr></tbody></table><hr><h3 id="cau-2-de-trac-nghiem" tabindex="-1">Câu 2 (Dễ): Trắc nghiệm <a class="header-anchor" href="#cau-2-de-trac-nghiem" aria-label="Permalink to &quot;Câu 2 (Dễ): Trắc nghiệm&quot;">​</a></h3><blockquote><p>Thiết bị nào hoạt động ở Tầng 3 của mô hình OSI? A. Hub B. Switch C. Router D. Repeater</p></blockquote><p><strong>Đáp án: C – Router</strong></p><p><strong>Giải thích:</strong> Router hoạt động ở Tầng 3 (Network Layer), đọc địa chỉ IP để định tuyến packet qua các mạng khác nhau. Switch ở Tầng 2 (dùng MAC), Hub và Repeater ở Tầng 1 (chỉ khuếch đại tín hiệu).</p><hr><h3 id="cau-3-trung-binh-xac-đinh-tang-osi" tabindex="-1">Câu 3 (Trung bình): Xác định tầng OSI <a class="header-anchor" href="#cau-3-trung-binh-xac-đinh-tang-osi" aria-label="Permalink to &quot;Câu 3 (Trung bình): Xác định tầng OSI&quot;">​</a></h3><blockquote><p>Xác định tầng OSI tương ứng với mỗi giao thức/công nghệ sau: a) HTTP b) IP c) Ethernet d) TCP e) SSL/TLS</p></blockquote><p><strong>Đáp án:</strong></p><table tabindex="0"><thead><tr><th>Giao thức</th><th>Tầng OSI</th></tr></thead><tbody><tr><td>HTTP</td><td>Tầng 7 – Application</td></tr><tr><td>IP</td><td>Tầng 3 – Network</td></tr><tr><td>Ethernet</td><td>Tầng 2 – Data Link</td></tr><tr><td>TCP</td><td>Tầng 4 – Transport</td></tr><tr><td>SSL/TLS</td><td>Tầng 6 – Presentation</td></tr></tbody></table><hr><h3 id="cau-4-trung-binh-phan-tich-qua-trinh-gui-du-lieu" tabindex="-1">Câu 4 (Trung bình): Phân tích quá trình gửi dữ liệu <a class="header-anchor" href="#cau-4-trung-binh-phan-tich-qua-trinh-gui-du-lieu" aria-label="Permalink to &quot;Câu 4 (Trung bình): Phân tích quá trình gửi dữ liệu&quot;">​</a></h3><blockquote><p>Khi bạn mở trang <code>https://google.com</code>, dữ liệu request đi qua 7 tầng OSI như thế nào? Hãy mô tả ngắn gọn hành động tại tầng 7, 4, 3, và 2.</p></blockquote><p><strong>Đáp án:</strong></p><ul><li><strong>Tầng 7 (Application):</strong> Trình duyệt tạo HTTP GET request, dùng giao thức HTTPS.</li><li><strong>Tầng 4 (Transport):</strong> TCP tạo segment, gắn port nguồn (ngẫu nhiên) và port đích (443 – HTTPS).</li><li><strong>Tầng 3 (Network):</strong> IP đóng gói segment thành packet, gắn IP nguồn (IP máy bạn) và IP đích (IP của Google).</li><li><strong>Tầng 2 (Data Link):</strong> Gắn địa chỉ MAC nguồn (card mạng của bạn) và MAC đích (router). Tạo Frame để truyền trong LAN.</li></ul><hr><h3 id="cau-5-van-dung-tinh-huong-thuc-te" tabindex="-1">Câu 5 (Vận dụng): Tình huống thực tế <a class="header-anchor" href="#cau-5-van-dung-tinh-huong-thuc-te" aria-label="Permalink to &quot;Câu 5 (Vận dụng): Tình huống thực tế&quot;">​</a></h3><blockquote><p>Kỹ thuật viên phát hiện máy tính không thể kết nối Internet nhưng vẫn ping được máy tính khác trong cùng mạng LAN. Vấn đề nằm ở tầng OSI nào? Giải thích.</p></blockquote><p><strong>Đáp án:</strong> Vấn đề nằm ở <strong>Tầng 3 (Network Layer)</strong> trở lên.</p><p><strong>Giải thích:</strong></p><ul><li>Máy tính vẫn ping được trong LAN → Tầng 1 (Physical), Tầng 2 (Data Link) hoạt động bình thường – cáp tốt, switch tốt, địa chỉ MAC nhận diện được.</li><li>Không ra được Internet → Có thể lỗi ở Tầng 3: địa chỉ IP sai, subnet mask sai, gateway mặc định (router) chưa được cấu hình, hoặc router gặp sự cố.</li><li>Cần kiểm tra: địa chỉ IP, subnet mask, default gateway bằng lệnh <code>ipconfig</code> (Windows).</li></ul><hr><h2 id="🔹-9-loi-thuong-gap" tabindex="-1">🔹 9. LỖI THƯỜNG GẶP <a class="header-anchor" href="#🔹-9-loi-thuong-gap" aria-label="Permalink to &quot;🔹 9. LỖI THƯỜNG GẶP&quot;">​</a></h2><h3 id="❌-loi-1-nham-so-tang-va-ten-tang" tabindex="-1">❌ Lỗi 1: Nhầm số tầng và tên tầng <a class="header-anchor" href="#❌-loi-1-nham-so-tang-va-ten-tang" aria-label="Permalink to &quot;❌ Lỗi 1: Nhầm số tầng và tên tầng&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Tầng 1 là Application, Tầng 7 là Physical.&quot;</p><p><strong>Đúng:</strong> Ngược lại – <strong>Tầng 1 là Physical</strong> (vật lý, thấp nhất), <strong>Tầng 7 là Application</strong> (ứng dụng, cao nhất). Nhớ: số tầng <strong>tăng dần từ dưới lên</strong> (từ phần cứng đến phần mềm).</p><hr><h3 id="❌-loi-2-nham-router-va-switch-voi-tang-osi" tabindex="-1">❌ Lỗi 2: Nhầm Router và Switch với tầng OSI <a class="header-anchor" href="#❌-loi-2-nham-router-va-switch-voi-tang-osi" aria-label="Permalink to &quot;❌ Lỗi 2: Nhầm Router và Switch với tầng OSI&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Switch hoạt động ở Tầng 3, Router ở Tầng 2.&quot;</p><p><strong>Đúng:</strong> <strong>Switch</strong> ở <strong>Tầng 2</strong> (dùng MAC address), <strong>Router</strong> ở <strong>Tầng 3</strong> (dùng IP address). Dùng mẹo: R(outer) → R(outing) → R(3ầng 3).</p><hr><h3 id="❌-loi-3-nham-đon-vi-du-lieu" tabindex="-1">❌ Lỗi 3: Nhầm đơn vị dữ liệu <a class="header-anchor" href="#❌-loi-3-nham-đon-vi-du-lieu" aria-label="Permalink to &quot;❌ Lỗi 3: Nhầm đơn vị dữ liệu&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Gói tin (packet) được tạo ra ở Tầng 2.&quot;</p><p><strong>Đúng:</strong> <strong>Packet</strong> được tạo ở <strong>Tầng 3 (Network)</strong>. Tầng 2 tạo <strong>Frame</strong>, Tầng 4 tạo <strong>Segment</strong>, Tầng 1 truyền <strong>Bit</strong>. Nhớ: <strong>P</strong>acket = <strong>P</strong>hần 3 (tầng 3).</p><hr><h3 id="❌-loi-4-nghi-osi-va-tcp-ip-la-giong-nhau-hoan-toan" tabindex="-1">❌ Lỗi 4: Nghĩ OSI và TCP/IP là giống nhau hoàn toàn <a class="header-anchor" href="#❌-loi-4-nghi-osi-va-tcp-ip-la-giong-nhau-hoan-toan" aria-label="Permalink to &quot;❌ Lỗi 4: Nghĩ OSI và TCP/IP là giống nhau hoàn toàn&quot;">​</a></h3><p><strong>Sai:</strong> &quot;TCP/IP cũng có 7 tầng như OSI.&quot;</p><p><strong>Đúng:</strong> TCP/IP chỉ có <strong>4 tầng</strong>. Nó gộp tầng 7+6+5 thành <strong>Application</strong>, gộp tầng 2+1 thành <strong>Network Access</strong>. OSI là mô hình lý thuyết, TCP/IP là mô hình thực tế được dùng trên Internet ngày nay.</p><hr><h3 id="❌-loi-5-nghi-phan-mem-nhu-chrome-word-la-tang-7" tabindex="-1">❌ Lỗi 5: Nghĩ phần mềm như Chrome, Word là &quot;Tầng 7&quot; <a class="header-anchor" href="#❌-loi-5-nghi-phan-mem-nhu-chrome-word-la-tang-7" aria-label="Permalink to &quot;❌ Lỗi 5: Nghĩ phần mềm như Chrome, Word là &quot;Tầng 7&quot;&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Chrome là ứng dụng nên nó là Tầng 7 của OSI.&quot;</p><p><strong>Đúng:</strong> Chrome (trình duyệt) là <strong>phần mềm người dùng</strong>, không phải Tầng 7. Tầng 7 (Application Layer) là các <strong>giao thức mạng</strong> mà Chrome sử dụng – cụ thể là <strong>HTTP/HTTPS</strong>. Tầng 7 không phải là ứng dụng, mà là giao thức mà ứng dụng dùng để giao tiếp qua mạng.</p><hr><h3 id="❌-loi-6-nghi-ung-dung-nhu-chrome-hoat-đong-o-tang-7" tabindex="-1">❌ Lỗi 6: Nghĩ ứng dụng như Chrome hoạt động ở Tầng 7 <a class="header-anchor" href="#❌-loi-6-nghi-ung-dung-nhu-chrome-hoat-đong-o-tang-7" aria-label="Permalink to &quot;❌ Lỗi 6: Nghĩ ứng dụng như Chrome hoạt động ở Tầng 7&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Google Chrome là phần mềm ứng dụng, nên Chrome hoạt động ở Tầng 7.&quot;</p><p><strong>Đúng:</strong> Tầng 7 (Application) là <strong>giao thức ứng dụng</strong> (HTTP, SMTP, FTP), không phải phần mềm ứng dụng. Chrome là trình duyệt, nhưng nó <strong>sử dụng</strong> giao thức HTTP/HTTPS (Tầng 7) để giao tiếp. Bản thân Chrome không &quot;là&quot; Tầng 7 – HTTP mới là.</p><hr><h3 id="❌-loi-7-nham-đon-vi-du-lieu-cua-cac-tang" tabindex="-1">❌ Lỗi 7: Nhầm đơn vị dữ liệu của các tầng <a class="header-anchor" href="#❌-loi-7-nham-đon-vi-du-lieu-cua-cac-tang" aria-label="Permalink to &quot;❌ Lỗi 7: Nhầm đơn vị dữ liệu của các tầng&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Tất cả các tầng đều gọi đơn vị dữ liệu là packet.&quot;</p><p><strong>Đúng:</strong> Mỗi tầng có đơn vị riêng: Tầng 7-5 = <strong>Data</strong>, Tầng 4 = <strong>Segment</strong> (TCP) / <strong>Datagram</strong> (UDP), Tầng 3 = <strong>Packet</strong>, Tầng 2 = <strong>Frame</strong>, Tầng 1 = <strong>Bit</strong>. Nhớ từ dưới lên: Bit, Frame, Packet, Segment, Data.</p><hr><h3 id="❌-loi-8-nghi-mo-hinh-osi-đuoc-dung-truc-tiep-trong-internet" tabindex="-1">❌ Lỗi 8: Nghĩ mô hình OSI được dùng trực tiếp trong Internet <a class="header-anchor" href="#❌-loi-8-nghi-mo-hinh-osi-đuoc-dung-truc-tiep-trong-internet" aria-label="Permalink to &quot;❌ Lỗi 8: Nghĩ mô hình OSI được dùng trực tiếp trong Internet&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Internet sử dụng mô hình OSI 7 tầng để truyền dữ liệu.&quot;</p><p><strong>Đúng:</strong> Internet thực sự dùng <strong>mô hình TCP/IP</strong> (4 tầng), không phải OSI. OSI là <strong>mô hình tham chiếu</strong> (reference model) dùng để giảng dạy và thiết kế giao thức. TCP/IP là mô hình <strong>thực tiễn</strong> được triển khai thực tế.</p><hr><h3 id="❌-loi-9-nham-ssl-tls-hoat-đong-o-tang-4" tabindex="-1">❌ Lỗi 9: Nhầm SSL/TLS hoạt động ở Tầng 4 <a class="header-anchor" href="#❌-loi-9-nham-ssl-tls-hoat-đong-o-tang-4" aria-label="Permalink to &quot;❌ Lỗi 9: Nhầm SSL/TLS hoạt động ở Tầng 4&quot;">​</a></h3><p><strong>Sai:</strong> &quot;SSL/TLS bảo mật kết nối TCP nên thuộc Tầng 4.&quot;</p><p><strong>Đúng:</strong> <strong>SSL/TLS</strong> hoạt động ở <strong>Tầng 6 (Presentation)</strong> trong OSI (mã hóa và chuyển đổi dữ liệu). Trong mô hình TCP/IP thực tế, TLS thường xem là một phần của lớp Application. TLS chạy <strong>trên TCP</strong> nhưng không phải là TCP.</p><hr><h3 id="❌-loi-10-nghi-tang-physical-chi-la-day-cap" tabindex="-1">❌ Lỗi 10: Nghĩ Tầng Physical chỉ là dây cáp <a class="header-anchor" href="#❌-loi-10-nghi-tang-physical-chi-la-day-cap" aria-label="Permalink to &quot;❌ Lỗi 10: Nghĩ Tầng Physical chỉ là dây cáp&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Tầng 1 (Physical) chỉ bao gồm cáp mạng.&quot;</p><p><strong>Đúng:</strong> Tầng Physical bao gồm mọi phương tiện truyền tín hiệu bit: cáp đồng (UTP/STP), cáp quang (fiber), sóng vô tuyến (Wi-Fi, Bluetooth, 4G/5G), cáp đồng trục, và cả tiêu chuẩn điện áp, tần số, connector. Hub và repeater cũng hoạt động ở Tầng 1.</p><hr><h3 id="❌-loi-11-nham-giua-mo-hinh-tcp-ip-4-tang-va-5-tang" tabindex="-1">❌ Lỗi 11: Nhầm giữa mô hình TCP/IP 4 tầng và 5 tầng <a class="header-anchor" href="#❌-loi-11-nham-giua-mo-hinh-tcp-ip-4-tang-va-5-tang" aria-label="Permalink to &quot;❌ Lỗi 11: Nhầm giữa mô hình TCP/IP 4 tầng và 5 tầng&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Mô hình TCP/IP có 4 tầng: Application, Transport, Internet, Network Access.&quot;</p><p><strong>Đúng:</strong> Có <strong>hai cách trình bày</strong> mô hình TCP/IP. Mô hình gốc 4 tầng: Application, Transport, Internet, Network Access. Mô hình cập nhật 5 tầng: Application, Transport, Network, Data Link, Physical. Cả hai đều đúng trong ngữ cảnh khác nhau – cần biết đang dùng cách nào.</p><hr><h3 id="❌-loi-12-nghi-tang-session-khong-con-đuoc-dung" tabindex="-1">❌ Lỗi 12: Nghĩ Tầng Session không còn được dùng <a class="header-anchor" href="#❌-loi-12-nghi-tang-session-khong-con-đuoc-dung" aria-label="Permalink to &quot;❌ Lỗi 12: Nghĩ Tầng Session không còn được dùng&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Tầng 5 (Session) là lý thuyết, không có giao thức thực tế nào.&quot;</p><p><strong>Đúng:</strong> Tầng Session có giao thức thực tế: <strong>NetBIOS</strong> (mạng Windows cũ), <strong>RPC (Remote Procedure Call)</strong>, <strong>PPTP</strong> (VPN). Trong mô hình TCP/IP, chức năng Session được tích hợp vào Tầng Application. Ví dụ: HTTP session (cookies), WebSocket sessions.</p><hr><h3 id="❌-loi-13-nham-encapsulation-voi-encryption" tabindex="-1">❌ Lỗi 13: Nhầm encapsulation với encryption <a class="header-anchor" href="#❌-loi-13-nham-encapsulation-voi-encryption" aria-label="Permalink to &quot;❌ Lỗi 13: Nhầm encapsulation với encryption&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Encapsulation mã hóa dữ liệu ở mỗi tầng.&quot;</p><p><strong>Đúng:</strong> <strong>Encapsulation (đóng gói)</strong> là thêm header (và đôi khi trailer) vào dữ liệu ở mỗi tầng khi đi xuống. Đây là bao bọc thêm thông tin điều khiển, không phải mã hóa. <strong>Encryption</strong> là biến dữ liệu thành dạng không đọc được. Encapsulation thêm header, encryption che giấu nội dung.</p><hr><h3 id="❌-loi-14-nghi-qua-trinh-decapsulation-xay-ra-o-tang-thap-nhat" tabindex="-1">❌ Lỗi 14: Nghĩ quá trình decapsulation xảy ra ở tầng thấp nhất <a class="header-anchor" href="#❌-loi-14-nghi-qua-trinh-decapsulation-xay-ra-o-tang-thap-nhat" aria-label="Permalink to &quot;❌ Lỗi 14: Nghĩ quá trình decapsulation xảy ra ở tầng thấp nhất&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Bên nhận mở gói tin (decapsulation) ở Tầng 1 Physical.&quot;</p><p><strong>Đúng:</strong> <strong>Decapsulation</strong> xảy ra từ dưới lên: Tầng 1 nhận bit, Tầng 2 loại bỏ MAC header để lấy IP packet, Tầng 3 loại bỏ IP header để lấy TCP segment, Tầng 4 loại bỏ TCP header để lấy dữ liệu ứng dụng, Tầng 7 hiển thị nội dung cho người dùng.</p><hr><h3 id="❌-loi-15-nham-tang-2-voi-tang-3-cho-switch-layer-3" tabindex="-1">❌ Lỗi 15: Nhầm Tầng 2 với Tầng 3 cho switch Layer 3 <a class="header-anchor" href="#❌-loi-15-nham-tang-2-voi-tang-3-cho-switch-layer-3" aria-label="Permalink to &quot;❌ Lỗi 15: Nhầm Tầng 2 với Tầng 3 cho switch Layer 3&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Switch Layer 3 không tồn tại, switch luôn là Tầng 2.&quot;</p><p><strong>Đúng:</strong> <strong>Switch Layer 3</strong> là switch có tính năng định tuyến (routing) – hoạt động cả ở Tầng 2 (switching) và Tầng 3 (routing giữa các VLAN). Đây là thiết bị phổ biến trong mạng doanh nghiệp, đắt hơn switch Layer 2 thường, nhưng không cần router riêng để định tuyến giữa các VLAN.</p><hr><h3 id="❌-loi-16-nghi-data-o-tang-7-khong-co-header" tabindex="-1">❌ Lỗi 16: Nghĩ &quot;data&quot; ở Tầng 7 không có header <a class="header-anchor" href="#❌-loi-16-nghi-data-o-tang-7-khong-co-header" aria-label="Permalink to &quot;❌ Lỗi 16: Nghĩ &quot;data&quot; ở Tầng 7 không có header&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Dữ liệu ứng dụng không có header, chỉ tầng dưới mới có.&quot;</p><p><strong>Đúng:</strong> Tầng Application (và các tầng trên) <strong>cũng có header</strong> trong dữ liệu của chúng – chỉ là không gọi là &quot;header&quot; theo kiểu OSI. HTTP request có dòng method, URL, headers, body. Email có From, To, Subject headers. Đây là application-level headers, nằm trong &quot;Data&quot; của góc nhìn Tầng 4 trở xuống.</p><hr><h3 id="❌-loi-17-nham-peer-layer-communication-voi-actual-data-flow" tabindex="-1">❌ Lỗi 17: Nhầm peer-layer communication với actual data flow <a class="header-anchor" href="#❌-loi-17-nham-peer-layer-communication-voi-actual-data-flow" aria-label="Permalink to &quot;❌ Lỗi 17: Nhầm peer-layer communication với actual data flow&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Tầng 3 trên máy A giao tiếp trực tiếp với Tầng 3 trên máy B mà không qua các tầng khác.&quot;</p><p><strong>Đúng:</strong> Giao tiếp ngang hàng (peer-layer) là <strong>khái niệm logic</strong> – Tầng 3 A &quot;nói chuyện&quot; với Tầng 3 B thông qua giao thức IP chung. Nhưng <strong>thực tế vật lý</strong>, dữ liệu phải đi xuống qua toàn bộ các tầng thấp hơn ở máy A, qua mạng vật lý, rồi lên qua các tầng ở máy B.</p><hr><h3 id="❌-loi-18-nghi-giao-thuc-o-tang-tren-khong-the-anh-huong-tang-duoi" tabindex="-1">❌ Lỗi 18: Nghĩ giao thức ở tầng trên không thể ảnh hưởng tầng dưới <a class="header-anchor" href="#❌-loi-18-nghi-giao-thuc-o-tang-tren-khong-the-anh-huong-tang-duoi" aria-label="Permalink to &quot;❌ Lỗi 18: Nghĩ giao thức ở tầng trên không thể ảnh hưởng tầng dưới&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Các tầng OSI độc lập hoàn toàn, tầng trên không ảnh hưởng tầng dưới.&quot;</p><p><strong>Đúng:</strong> Các tầng có <strong>abstraction</strong> nhưng không hoàn toàn độc lập. Ví dụ: kích thước dữ liệu ứng dụng ảnh hưởng đến TCP segmentation; TCP window size ảnh hưởng đến lưu lượng mạng; QoS ở Tầng 3 cần đọc thông tin từ Tầng 4 (port number) để phân loại lưu lượng.</p><hr><h3 id="❌-loi-19-nham-bridge-voi-switch" tabindex="-1">❌ Lỗi 19: Nhầm bridge với switch <a class="header-anchor" href="#❌-loi-19-nham-bridge-voi-switch" aria-label="Permalink to &quot;❌ Lỗi 19: Nhầm bridge với switch&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Bridge và switch là hoàn toàn khác nhau về nguyên lý.&quot;</p><p><strong>Đúng:</strong> <strong>Bridge</strong> là thiết bị ban đầu kết nối hai đoạn mạng ở Tầng 2. <strong>Switch</strong> thực chất là <strong>multi-port bridge</strong> – cùng nguyên lý nhưng có nhiều cổng hơn và hiệu năng cao hơn. Switch hiện đại là bridge thế hệ mới, cải tiến thêm nhiều tính năng.</p><hr><h3 id="❌-loi-20-nghi-tang-presentation-chi-dung-đe-nen-file" tabindex="-1">❌ Lỗi 20: Nghĩ Tầng Presentation chỉ dùng để nén file <a class="header-anchor" href="#❌-loi-20-nghi-tang-presentation-chi-dung-đe-nen-file" aria-label="Permalink to &quot;❌ Lỗi 20: Nghĩ Tầng Presentation chỉ dùng để nén file&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Tầng 6 chỉ làm nhiệm vụ nén file ZIP.&quot;</p><p><strong>Đúng:</strong> Tầng Presentation thực hiện nhiều chức năng: <strong>mã hóa/giải mã</strong> (SSL/TLS), <strong>nén/giải nén</strong> dữ liệu (JPEG, MP3, ZIP), <strong>chuyển đổi định dạng ký tự</strong> (ASCII ↔ EBCDIC), và <strong>serialization</strong> (biến đối tượng thành luồng byte). Đây là tầng &quot;dịch ngôn ngữ&quot; giữa máy.</p><hr><h3 id="❌-loi-21-nham-ip-packet-voi-ethernet-frame" tabindex="-1">❌ Lỗi 21: Nhầm IP packet với Ethernet frame <a class="header-anchor" href="#❌-loi-21-nham-ip-packet-voi-ethernet-frame" aria-label="Permalink to &quot;❌ Lỗi 21: Nhầm IP packet với Ethernet frame&quot;">​</a></h3><p><strong>Sai:</strong> &quot;IP packet và Ethernet frame là tên gọi khác nhau cho cùng một thứ.&quot;</p><p><strong>Đúng:</strong> <strong>Ethernet frame (Tầng 2)</strong> bao bọc <strong>IP packet (Tầng 3)</strong>. Frame có MAC source/destination header + IP packet làm payload. Khi truyền từ LAN sang Internet, frame thay đổi (MAC mới) nhưng IP packet bên trong giữ nguyên.</p><hr><h3 id="❌-loi-22-nghi-tang-5-session-quan-ly-session-web" tabindex="-1">❌ Lỗi 22: Nghĩ Tầng 5 (Session) quản lý session web <a class="header-anchor" href="#❌-loi-22-nghi-tang-5-session-quan-ly-session-web" aria-label="Permalink to &quot;❌ Lỗi 22: Nghĩ Tầng 5 (Session) quản lý session web&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Session đăng nhập website được quản lý bởi Tầng 5 OSI.&quot;</p><p><strong>Đúng:</strong> Session đăng nhập web (HTTP session/cookie) được quản lý ở <strong>Tầng 7 (Application)</strong> bởi ứng dụng web server và browser. Tầng 5 OSI quản lý thiết lập/duy trì/kết thúc luồng giao tiếp cơ bản giữa hai ứng dụng, khác với khái niệm &quot;user session&quot; của web.</p><hr><h3 id="❌-loi-23-nham-smtp-voi-tang-4" tabindex="-1">❌ Lỗi 23: Nhầm SMTP với Tầng 4 <a class="header-anchor" href="#❌-loi-23-nham-smtp-voi-tang-4" aria-label="Permalink to &quot;❌ Lỗi 23: Nhầm SMTP với Tầng 4&quot;">​</a></h3><p><strong>Sai:</strong> &quot;SMTP là giao thức ở Tầng 4 vì nó gửi email qua TCP.&quot;</p><p><strong>Đúng:</strong> <strong>SMTP là giao thức Tầng 7 (Application)</strong>. SMTP quy định cách email được định dạng và gửi giữa mail servers. SMTP chạy <strong>trên TCP</strong> (Tầng 4), nhưng bản thân nó thuộc Tầng 7. Tương tự: HTTP chạy trên TCP nhưng là giao thức Tầng 7.</p><hr><h3 id="❌-loi-24-nghi-osi-va-tcp-ip-co-cung-so-tang" tabindex="-1">❌ Lỗi 24: Nghĩ OSI và TCP/IP có cùng số tầng <a class="header-anchor" href="#❌-loi-24-nghi-osi-va-tcp-ip-co-cung-so-tang" aria-label="Permalink to &quot;❌ Lỗi 24: Nghĩ OSI và TCP/IP có cùng số tầng&quot;">​</a></h3><p><strong>Sai:</strong> &quot;OSI và TCP/IP đều có 4 tầng.&quot;</p><p><strong>Đúng:</strong> <strong>OSI có 7 tầng</strong>, <strong>TCP/IP (gốc) có 4 tầng</strong>. TCP/IP gộp Tầng 7+6+5 thành Application, giữ Transport và Internet (Network), gộp Tầng 2+1 thành Network Access. TCP/IP đơn giản hơn và thực tế hơn OSI.</p><hr><h3 id="❌-loi-25-nghi-hub-hoat-đong-o-tang-2" tabindex="-1">❌ Lỗi 25: Nghĩ Hub hoạt động ở Tầng 2 <a class="header-anchor" href="#❌-loi-25-nghi-hub-hoat-đong-o-tang-2" aria-label="Permalink to &quot;❌ Lỗi 25: Nghĩ Hub hoạt động ở Tầng 2&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Hub kết nối nhiều máy tính như switch, nên cũng ở Tầng 2.&quot;</p><p><strong>Đúng:</strong> <strong>Hub hoạt động ở Tầng 1 (Physical)</strong> – nó chỉ khuếch đại và phát tán tín hiệu điện đến tất cả cổng, không đọc địa chỉ MAC. <strong>Switch ở Tầng 2</strong> – đọc MAC và gửi đúng cổng. Đây là lý do switch hiệu quả hơn hub rất nhiều.</p><hr><h3 id="❌-loi-26-nham-firewall-stateful-voi-stateless" tabindex="-1">❌ Lỗi 26: Nhầm firewall stateful với stateless <a class="header-anchor" href="#❌-loi-26-nham-firewall-stateful-voi-stateless" aria-label="Permalink to &quot;❌ Lỗi 26: Nhầm firewall stateful với stateless&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Tất cả firewall đều như nhau – đều lọc theo IP và port.&quot;</p><p><strong>Đúng:</strong> <strong>Stateless firewall</strong> lọc mỗi packet độc lập theo IP/port (Tầng 3-4). <strong>Stateful firewall</strong> theo dõi trạng thái kết nối (TCP state machine) – thông minh hơn. <strong>Application firewall (Layer 7)</strong> phân tích nội dung ứng dụng (HTTP headers, SQL injection patterns). Mỗi loại hoạt động ở tầng khác nhau.</p><hr><h3 id="❌-loi-27-nghi-mo-hinh-osi-đuoc-phat-trien-truoc-tcp-ip" tabindex="-1">❌ Lỗi 27: Nghĩ mô hình OSI được phát triển trước TCP/IP <a class="header-anchor" href="#❌-loi-27-nghi-mo-hinh-osi-đuoc-phat-trien-truoc-tcp-ip" aria-label="Permalink to &quot;❌ Lỗi 27: Nghĩ mô hình OSI được phát triển trước TCP/IP&quot;">​</a></h3><p><strong>Sai:</strong> &quot;TCP/IP được phát triển dựa trên mô hình OSI.&quot;</p><p><strong>Đúng:</strong> <strong>TCP/IP ra đời trước OSI</strong>. ARPANET dùng TCP/IP từ những năm 1970. OSI được ISO phát triển năm 1984 như mô hình chuẩn hóa quốc tế, <strong>sau khi</strong> TCP/IP đã được triển khai. OSI muốn thay TCP/IP nhưng thất bại – TCP/IP đã quá phổ biến.</p><hr><h3 id="❌-loi-28-nghi-moi-tang-chi-co-mot-giao-thuc" tabindex="-1">❌ Lỗi 28: Nghĩ mỗi tầng chỉ có một giao thức <a class="header-anchor" href="#❌-loi-28-nghi-moi-tang-chi-co-mot-giao-thuc" aria-label="Permalink to &quot;❌ Lỗi 28: Nghĩ mỗi tầng chỉ có một giao thức&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Tầng 4 chỉ có TCP, Tầng 3 chỉ có IP.&quot;</p><p><strong>Đúng:</strong> Mỗi tầng có nhiều giao thức. Tầng 4: TCP, UDP, SCTP, QUIC. Tầng 3: IPv4, IPv6, ICMP, ARP (Tầng 2-3 ranh giới), OSPF, BGP. Tầng 2: Ethernet, Wi-Fi (802.11), PPP. Tầng 7: HTTP, HTTPS, SMTP, FTP, DNS, SSH... Mô hình OSI là framework, không giới hạn số giao thức mỗi tầng.</p><hr><h3 id="❌-loi-29-nham-load-balancer-voi-switch-layer-3" tabindex="-1">❌ Lỗi 29: Nhầm load balancer với switch Layer 3 <a class="header-anchor" href="#❌-loi-29-nham-load-balancer-voi-switch-layer-3" aria-label="Permalink to &quot;❌ Lỗi 29: Nhầm load balancer với switch Layer 3&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Load balancer là switch Layer 3 vì nó cũng phân phối traffic.&quot;</p><p><strong>Đúng:</strong> <strong>Load balancer</strong> hoạt động ở nhiều tầng tùy loại: Layer 4 (dựa trên IP/TCP), hoặc <strong>Layer 7</strong> (dựa trên URL, HTTP headers, cookies). Layer 7 load balancer đọc nội dung HTTP request để quyết định server nào xử lý – phức tạp hơn nhiều so với routing Tầng 3.</p><hr><h3 id="❌-loi-30-nghi-tang-2-frame-khong-co-trailer" tabindex="-1">❌ Lỗi 30: Nghĩ Tầng 2 frame không có trailer <a class="header-anchor" href="#❌-loi-30-nghi-tang-2-frame-khong-co-trailer" aria-label="Permalink to &quot;❌ Lỗi 30: Nghĩ Tầng 2 frame không có trailer&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Frame Tầng 2 chỉ có header, không có trailer.&quot;</p><p><strong>Đúng:</strong> Ethernet frame có <strong>FCS (Frame Check Sequence) trailer</strong> ở cuối – 4 byte CRC để phát hiện lỗi trong quá trình truyền. Nếu FCS không khớp, frame bị hủy. Đây là khác biệt so với IP packet (chỉ có header, không có trailer).</p><hr><h3 id="❌-loi-31-nghi-vpn-hoat-đong-o-mot-tang-co-đinh" tabindex="-1">❌ Lỗi 31: Nghĩ VPN hoạt động ở một tầng cố định <a class="header-anchor" href="#❌-loi-31-nghi-vpn-hoat-đong-o-mot-tang-co-đinh" aria-label="Permalink to &quot;❌ Lỗi 31: Nghĩ VPN hoạt động ở một tầng cố định&quot;">​</a></h3><p><strong>Sai:</strong> &quot;VPN là công nghệ Tầng 3.&quot;</p><p><strong>Đúng:</strong> VPN hoạt động ở nhiều tầng tùy công nghệ: <strong>IPsec (Layer 3)</strong>, <strong>SSL/TLS VPN (Layer 4-7)</strong>, <strong>PPTP (Layer 2)</strong>, <strong>L2TP (Layer 2)</strong>. Mỗi loại có ưu nhược điểm khác nhau về bảo mật, hiệu năng, và khả năng xuyên qua NAT/firewall.</p><hr><h3 id="❌-loi-32-nham-pdu-voi-sdu" tabindex="-1">❌ Lỗi 32: Nhầm PDU với SDU <a class="header-anchor" href="#❌-loi-32-nham-pdu-voi-sdu" aria-label="Permalink to &quot;❌ Lỗi 32: Nhầm PDU với SDU&quot;">​</a></h3><p><strong>Sai:</strong> &quot;PDU và SDU là tên khác nhau cho đơn vị dữ liệu.&quot;</p><p><strong>Đúng:</strong> <strong>PDU (Protocol Data Unit)</strong> là đơn vị dữ liệu hoàn chỉnh của một tầng cụ thể (bao gồm header + payload). <strong>SDU (Service Data Unit)</strong> là dữ liệu được chuyển từ tầng trên xuống, trước khi tầng hiện tại thêm header. Ví dụ: TCP segment nhận IP payload (SDU) rồi thêm TCP header → tạo TCP segment (PDU).</p><hr><h3 id="❌-loi-33-nghi-arp-thuoc-tang-3" tabindex="-1">❌ Lỗi 33: Nghĩ ARP thuộc Tầng 3 <a class="header-anchor" href="#❌-loi-33-nghi-arp-thuoc-tang-3" aria-label="Permalink to &quot;❌ Lỗi 33: Nghĩ ARP thuộc Tầng 3&quot;">​</a></h3><p><strong>Sai:</strong> &quot;ARP dịch IP sang MAC nên thuộc Tầng 3 (Network).&quot;</p><p><strong>Đúng:</strong> <strong>ARP (Address Resolution Protocol)</strong> là giao thức ranh giới giữa Tầng 2 và Tầng 3. Về mặt chức năng, ARP liên quan đến địa chỉ IP (Tầng 3) và MAC (Tầng 2). Theo mô hình OSI, ARP thường được coi thuộc <strong>Tầng 2 hoặc 2.5</strong>. Trong TCP/IP, ARP nằm trong lớp Network Access.</p><hr><h3 id="❌-loi-34-nghi-bluetooth-hoat-đong-o-tang-7" tabindex="-1">❌ Lỗi 34: Nghĩ Bluetooth hoạt động ở Tầng 7 <a class="header-anchor" href="#❌-loi-34-nghi-bluetooth-hoat-đong-o-tang-7" aria-label="Permalink to &quot;❌ Lỗi 34: Nghĩ Bluetooth hoạt động ở Tầng 7&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Bluetooth là kết nối không dây như Wi-Fi, cả hai thuộc Tầng 7.&quot;</p><p><strong>Đúng:</strong> Bluetooth (như Wi-Fi) hoạt động ở <strong>Tầng 1 (Physical) và Tầng 2 (Data Link)</strong> – cung cấp kết nối không dây. Ứng dụng Bluetooth (profile: A2DP, HFP, OBEX) mới là Tầng cao hơn. Wi-Fi và Bluetooth đều là công nghệ truyền không dây ở tầng thấp.</p><hr><h3 id="❌-loi-35-nham-http-https-voi-tls-ssl" tabindex="-1">❌ Lỗi 35: Nhầm HTTP/HTTPS với TLS/SSL <a class="header-anchor" href="#❌-loi-35-nham-http-https-voi-tls-ssl" aria-label="Permalink to &quot;❌ Lỗi 35: Nhầm HTTP/HTTPS với TLS/SSL&quot;">​</a></h3><p><strong>Sai:</strong> &quot;HTTPS là một giao thức mới hoàn toàn, khác HTTP.&quot;</p><p><strong>Đúng:</strong> <strong>HTTPS = HTTP + TLS</strong>. Không phải giao thức mới – đây là HTTP thông thường nhưng được mã hóa bởi TLS. TLS hoạt động ở Tầng 6 (Presentation), cung cấp lớp bảo mật. HTTP vẫn là giao thức Tầng 7. Khi bạn dùng HTTPS, có hai lớp giao thức chồng lên nhau.</p><hr><h3 id="❌-loi-36-nghi-giao-thuc-tang-7-khong-the-anh-huong-bao-mat" tabindex="-1">❌ Lỗi 36: Nghĩ giao thức Tầng 7 không thể ảnh hưởng bảo mật <a class="header-anchor" href="#❌-loi-36-nghi-giao-thuc-tang-7-khong-the-anh-huong-bao-mat" aria-label="Permalink to &quot;❌ Lỗi 36: Nghĩ giao thức Tầng 7 không thể ảnh hưởng bảo mật&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Firewall bảo vệ ở Tầng 3-4 là đủ, Tầng 7 không cần.&quot;</p><p><strong>Đúng:</strong> Nhiều tấn công xảy ra ở Tầng 7: <strong>SQL injection</strong> (trong HTTP request body), <strong>XSS</strong> (trong HTML response), <strong>SMTP injection</strong> (trong email). Firewall thông thường không thể phát hiện các tấn công này. Cần <strong>WAF (Web Application Firewall)</strong> phân tích Tầng 7 để bảo vệ toàn diện.</p><hr><h3 id="❌-loi-37-nham-vlan-trunk-voi-network-trunk-isp" tabindex="-1">❌ Lỗi 37: Nhầm VLAN trunk với network trunk (ISP) <a class="header-anchor" href="#❌-loi-37-nham-vlan-trunk-voi-network-trunk-isp" aria-label="Permalink to &quot;❌ Lỗi 37: Nhầm VLAN trunk với network trunk (ISP)&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Trunk port trên switch giống như đường trunk của nhà mạng ISP.&quot;</p><p><strong>Đúng:</strong> <strong>VLAN trunk (802.1Q)</strong> là cổng switch có thể truyền dữ liệu của nhiều VLAN cùng lúc, dùng tag để phân biệt. <strong>Trunk trong ngữ cảnh ISP</strong> là đường kết nối dung lượng cao giữa các nút mạng. Cùng từ &quot;trunk&quot; nhưng ý nghĩa khác nhau trong hai ngữ cảnh.</p><hr><h3 id="❌-loi-38-nghi-ipv6-header-phuc-tap-hon-ipv4" tabindex="-1">❌ Lỗi 38: Nghĩ IPv6 header phức tạp hơn IPv4 <a class="header-anchor" href="#❌-loi-38-nghi-ipv6-header-phuc-tap-hon-ipv4" aria-label="Permalink to &quot;❌ Lỗi 38: Nghĩ IPv6 header phức tạp hơn IPv4&quot;">​</a></h3><p><strong>Sai:</strong> &quot;IPv6 có địa chỉ dài hơn nên header phức tạp và lớn hơn IPv4.&quot;</p><p><strong>Đúng:</strong> IPv6 header thực ra <strong>đơn giản hơn IPv4</strong>: IPv4 header có độ dài biến đổi (20–60 bytes, tùy options), IPv6 header có độ dài <strong>cố định 40 bytes</strong>, bỏ nhiều trường ít dùng (fragmentation xử lý theo cách khác). IPv6 được thiết kế để xử lý nhanh hơn ở router.</p><hr><h3 id="❌-loi-39-nham-giao-thuc-routing-voi-giao-thuc-routed" tabindex="-1">❌ Lỗi 39: Nhầm giao thức routing với giao thức routed <a class="header-anchor" href="#❌-loi-39-nham-giao-thuc-routing-voi-giao-thuc-routed" aria-label="Permalink to &quot;❌ Lỗi 39: Nhầm giao thức routing với giao thức routed&quot;">​</a></h3><p><strong>Sai:</strong> &quot;OSPF và IP là hai loại routing protocol.&quot;</p><p><strong>Đúng:</strong> <strong>Routed protocol (giao thức được định tuyến)</strong>: IP – là giao thức mang dữ liệu được định tuyến qua mạng. <strong>Routing protocol (giao thức định tuyến)</strong>: OSPF, BGP, RIP – là giao thức các router dùng để trao đổi thông tin định tuyến và xây dựng routing table. IP là giao thức cần được định tuyến; OSPF là giao thức giúp router biết đường đi.</p><hr><h3 id="❌-loi-40-nghi-tang-physical-chi-đinh-nghia-toc-đo-truyen" tabindex="-1">❌ Lỗi 40: Nghĩ Tầng Physical chỉ định nghĩa tốc độ truyền <a class="header-anchor" href="#❌-loi-40-nghi-tang-physical-chi-đinh-nghia-toc-đo-truyen" aria-label="Permalink to &quot;❌ Lỗi 40: Nghĩ Tầng Physical chỉ định nghĩa tốc độ truyền&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Tầng 1 chỉ quy định tốc độ truyền dữ liệu.&quot;</p><p><strong>Đúng:</strong> Tầng Physical quy định nhiều thứ hơn: <strong>mức điện áp</strong> (0V vs 5V), <strong>biểu diễn bit</strong> (Manchester encoding, NRZ), <strong>tốc độ baud</strong>, <strong>loại connector</strong> (RJ-45, SFP, BNC), <strong>loại cáp</strong> (UTP, STP, coaxial, fiber), <strong>số lượng dây</strong> trong cáp, và <strong>sơ đồ ghim</strong> (pinout).</p><hr><h3 id="❌-loi-41-nham-tang-4-voi-tang-ung-dung-trong-bao-mat" tabindex="-1">❌ Lỗi 41: Nhầm Tầng 4 với Tầng ứng dụng trong bảo mật <a class="header-anchor" href="#❌-loi-41-nham-tang-4-voi-tang-ung-dung-trong-bao-mat" aria-label="Permalink to &quot;❌ Lỗi 41: Nhầm Tầng 4 với Tầng ứng dụng trong bảo mật&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Kiểm soát truy cập theo port thuộc Tầng 7 (Application).&quot;</p><p><strong>Đúng:</strong> Kiểm soát theo <strong>port number</strong> (80, 443, 22) là <strong>Tầng 4</strong>. Kiểm soát theo nội dung ứng dụng (URL, HTTP headers, user-agent) là <strong>Tầng 7</strong>. Firewall Tầng 4 đơn giản hơn và nhanh hơn; WAF (Tầng 7) thông minh hơn nhưng tốn tài nguyên hơn.</p><hr><h3 id="❌-loi-42-nghi-mo-hinh-osi-đa-loi-thoi-va-khong-can-hoc" tabindex="-1">❌ Lỗi 42: Nghĩ mô hình OSI đã lỗi thời và không cần học <a class="header-anchor" href="#❌-loi-42-nghi-mo-hinh-osi-đa-loi-thoi-va-khong-can-hoc" aria-label="Permalink to &quot;❌ Lỗi 42: Nghĩ mô hình OSI đã lỗi thời và không cần học&quot;">​</a></h3><p><strong>Sai:</strong> &quot;OSI không dùng trong thực tế, không cần học.&quot;</p><p><strong>Đúng:</strong> Mặc dù TCP/IP được dùng thực tế, <strong>OSI vẫn là framework chuẩn</strong> để: troubleshoot mạng (xác định vấn đề ở tầng nào), thiết kế giao thức mới, giao tiếp giữa các kỹ sư mạng, và tài liệu kỹ thuật. Kỹ sư mạng dùng OSI để nói &quot;vấn đề ở Layer 2&quot; hoặc &quot;cần debug Layer 7&quot;.</p><hr><h3 id="❌-loi-43-nham-qos-dscp-voi-vlan-tagging" tabindex="-1">❌ Lỗi 43: Nhầm QoS DSCP với VLAN tagging <a class="header-anchor" href="#❌-loi-43-nham-qos-dscp-voi-vlan-tagging" aria-label="Permalink to &quot;❌ Lỗi 43: Nhầm QoS DSCP với VLAN tagging&quot;">​</a></h3><p><strong>Sai:</strong> &quot;DSCP và VLAN tag đều dùng để ưu tiên lưu lượng mạng.&quot;</p><p><strong>Đúng:</strong> <strong>VLAN tag (802.1Q)</strong> ở Tầng 2, xác định VLAN. <strong>DSCP (Differentiated Services Code Point)</strong> ở Tầng 3, trong IP header, dùng để đánh dấu QoS – ưu tiên lưu lượng quan trọng (voice call, video conference) hơn lưu lượng thông thường (tải file). Hai cơ chế khác nhau ở tầng khác nhau.</p><hr><h3 id="❌-loi-44-nghi-fragmentation-xay-ra-o-tang-4" tabindex="-1">❌ Lỗi 44: Nghĩ fragmentation xảy ra ở Tầng 4 <a class="header-anchor" href="#❌-loi-44-nghi-fragmentation-xay-ra-o-tang-4" aria-label="Permalink to &quot;❌ Lỗi 44: Nghĩ fragmentation xảy ra ở Tầng 4&quot;">​</a></h3><p><strong>Sai:</strong> &quot;TCP phân mảnh dữ liệu, IP chỉ định tuyến.&quot;</p><p><strong>Đúng:</strong> Có hai mức phân mảnh: <strong>TCP segmentation (Tầng 4)</strong> chia dữ liệu thành segment theo MSS. <strong>IP fragmentation (Tầng 3)</strong> chia IP packet nhỏ hơn khi MTU của mạng trung gian nhỏ hơn kích thước packet. Fragmentation IP cần được reassemble ở đầu nhận, gây overhead. IPv6 không hỗ trợ fragmentation tại router (chỉ tại nguồn).</p><hr><h3 id="❌-loi-45-nham-proxy-server-voi-gateway" tabindex="-1">❌ Lỗi 45: Nhầm proxy server với gateway <a class="header-anchor" href="#❌-loi-45-nham-proxy-server-voi-gateway" aria-label="Permalink to &quot;❌ Lỗi 45: Nhầm proxy server với gateway&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Proxy server và gateway là như nhau.&quot;</p><p><strong>Đúng:</strong> <strong>Gateway</strong> là thiết bị kết nối hai mạng khác nhau (thường là router). <strong>Proxy server</strong> là trung gian ở Tầng 7 – nhận request từ client, thay client gửi đến server đích, rồi trả kết quả về. Proxy có thể cache, lọc nội dung, ẩn địa chỉ IP client. Gateway hoạt động ở tầng thấp hơn và không thao túng nội dung ứng dụng.</p><hr><h3 id="❌-loi-46-nghi-icmp-echo-reply-la-giao-thuc-tang-4" tabindex="-1">❌ Lỗi 46: Nghĩ ICMP Echo Reply là giao thức Tầng 4 <a class="header-anchor" href="#❌-loi-46-nghi-icmp-echo-reply-la-giao-thuc-tang-4" aria-label="Permalink to &quot;❌ Lỗi 46: Nghĩ ICMP Echo Reply là giao thức Tầng 4&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Ping dùng ICMP Echo, ICMP Reply thuộc Tầng 4 Transport.&quot;</p><p><strong>Đúng:</strong> <strong>ICMP (Internet Control Message Protocol)</strong> là giao thức Tầng 3 (Network), cùng tầng với IP. ICMP không phải là giao thức transport như TCP/UDP – nó dùng để báo cáo lỗi và kiểm tra kết nối giữa các router/host. ICMP messages được đóng gói trong IP packets.</p><hr><h3 id="❌-loi-47-nham-mtu-voi-mss" tabindex="-1">❌ Lỗi 47: Nhầm MTU với MSS <a class="header-anchor" href="#❌-loi-47-nham-mtu-voi-mss" aria-label="Permalink to &quot;❌ Lỗi 47: Nhầm MTU với MSS&quot;">​</a></h3><p><strong>Sai:</strong> &quot;MTU và MSS đều là kích thước tối đa của một gói tin mạng.&quot;</p><p><strong>Đúng:</strong> <strong>MTU (Maximum Transmission Unit)</strong> là kích thước tối đa của Ethernet frame ở Tầng 2 (thường 1500 bytes payload). <strong>MSS (Maximum Segment Size)</strong> là kích thước tối đa dữ liệu trong một TCP segment ở Tầng 4, tính toán từ MTU trừ IP header (20 bytes) và TCP header (20 bytes) = 1460 bytes thông thường.</p><hr><h3 id="❌-loi-48-nghi-spanning-tree-protocol-stp-thuoc-tang-3" tabindex="-1">❌ Lỗi 48: Nghĩ Spanning Tree Protocol (STP) thuộc Tầng 3 <a class="header-anchor" href="#❌-loi-48-nghi-spanning-tree-protocol-stp-thuoc-tang-3" aria-label="Permalink to &quot;❌ Lỗi 48: Nghĩ Spanning Tree Protocol (STP) thuộc Tầng 3&quot;">​</a></h3><p><strong>Sai:</strong> &quot;STP ngăn vòng lặp trong mạng nên thuộc Tầng 3 như routing.&quot;</p><p><strong>Đúng:</strong> <strong>STP (Spanning Tree Protocol – 802.1D)</strong> là giao thức <strong>Tầng 2</strong> – ngăn vòng lặp trong mạng switch (Ethernet loops). Routing ở Tầng 3 ngăn vòng lặp IP bằng TTL và routing tables. STP dùng Bridge Protocol Data Units (BPDU) để giao tiếp giữa các switch.</p><hr><h3 id="❌-loi-49-nghi-tang-6-khong-can-thiet" tabindex="-1">❌ Lỗi 49: Nghĩ Tầng 6 không cần thiết <a class="header-anchor" href="#❌-loi-49-nghi-tang-6-khong-can-thiet" aria-label="Permalink to &quot;❌ Lỗi 49: Nghĩ Tầng 6 không cần thiết&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Tầng Presentation không làm gì quan trọng, bỏ qua cũng được.&quot;</p><p><strong>Đúng:</strong> Tầng Presentation giải quyết vấn đề <strong>khác biệt định dạng giữa các hệ thống</strong>: máy Big-endian và Little-endian biểu diễn số nguyên khác nhau; ký tự encoding khác nhau (UTF-8, UTF-16, Latin-1). Không có Tầng 6, ứng dụng phải tự xử lý những vấn đề này – làm tăng độ phức tạp của code ứng dụng.</p><hr><h3 id="❌-loi-50-nham-giao-thuc-hoat-đong-o-tang-x-voi-chi-dung-tang-x" tabindex="-1">❌ Lỗi 50: Nhầm giao thức &quot;hoạt động ở tầng X&quot; với &quot;chỉ dùng tầng X&quot; <a class="header-anchor" href="#❌-loi-50-nham-giao-thuc-hoat-đong-o-tang-x-voi-chi-dung-tang-x" aria-label="Permalink to &quot;❌ Lỗi 50: Nhầm giao thức &quot;hoạt động ở tầng X&quot; với &quot;chỉ dùng tầng X&quot;&quot;">​</a></h3><p><strong>Sai:</strong> &quot;HTTP hoạt động ở Tầng 7, nghĩa là nó không cần Tầng 1-6.&quot;</p><p><strong>Đúng:</strong> Khi nói giao thức &quot;hoạt động ở Tầng X&quot;, có nghĩa là giao thức đó <strong>thêm chức năng ở Tầng X</strong>. Để thực sự truyền dữ liệu, <strong>tất cả các tầng bên dưới đều cần thiết</strong>. HTTP cần TCP (Tầng 4) để tin cậy, IP (Tầng 3) để định tuyến, Ethernet (Tầng 2) cho LAN, và cáp/sóng vô tuyến (Tầng 1) để truyền vật lý.</p>`,295)])])}const p=t(i,[["render",h]]);export{d as __pageData,p as default};
